- `require` can only be used with `default` export as it was in 0.x versions;
- `import` can be used with both `default` & `named` exports;

Detailed:
- Added browser CommonJS bundle to the build pipeline;
- Fixed exports entry points;
- Added module exports tests;
- Added missing ESM export for parity with Axios factory; 
- Added `toFormData`, `formToJSON`, `isAxiosError`, `spread`, `isCancel`, `all` as named export to `index.d.ts`;

In an attempt to bring order, the package export has been refactored. The following rules were adopted:
- CommonJS module has only factory as default export, as it was before
- CommonJS entry point to build the cjs bundle is `./lib/axios.js`
- ESM entry provides both default (factory) and named exports;
- ESM entry point is `./index.js`. This module should expand Axios factory export as ESM named export. This module should not be used for purposes other than re-export features as a named export.
- Named export should be in parity with export provided by Axios factory
- The `./dist/axios.js` and `./dist/esm/axios.js` bundles are for CDN usage only.

Closes #5154; Closes #5164; Closes #5169; Closes #5091; Closes #5130; Closes #5118; Closes #5011; Closes #5031; Closes #5044; Closes #5082;
Related: #5101, #5026, #5088

Users that import the module with `require` will do it as it was before:

```js
const axios = require('axios');

console.log(axios.isCancel('something'));
console.log(new axios.AxiosError('oops'));
```
If the module is loaded with `import` statement you can use both named and factory exports:

```js
import axios from 'axios';

console.log(axios.isCancel('something'));
console.log(new axios.AxiosError('oops'));
```
OR
```js
import axios, {isCancel, AxiosError} from 'axios';

console.log(isCancel('something'));
console.log(new AxiosError('oops'));
```
If something goes wrong (custom/outdated environment), you can try to load CommonJS bundle directly:
```js
const axios = require('axios/dist/browser/axios.cjs'); // browser
// const axios = require('axios/dist/node/axios.cjs'); // node

console.log(axios.isCancel('something'));
console.log(new axios.AxiosError('oops'));
```"}}},{"event":"cross-referenced","created_at":"2022-10-22T23:31:54Z","source":{"issue":{"number":9,"title":"Upgrade to Latest Nx (15.0.1) and Update Dependencies","html_url":"https://github.com/imyourmanzi/SpotifyPlaylistManager/pull/9","repository":{"full_name":"imyourmanzi/SpotifyPlaylistManager"},"pull_request":{"merged_at":"2022-10-22T23:36:10Z","html_url":"https://github.com/imyourmanzi/SpotifyPlaylistManager/pull/9"}}}},{"event":"cross-referenced","created_at":"2022-10-28T10:20:47Z","source":{"issue":{"number":68,"title":"fix: workaround for an axios issue","html_url":"https://github.com/hacocms/hacocms-js-sdk/pull/68","repository":{"full_name":"hacocms/hacocms-js-sdk"},"pull_request":{"merged_at":"2022-10-31T01:58:14Z","html_url":"https://github.com/hacocms/hacocms-js-sdk/pull/68"}}}},{"event":"closed","created_at":"2022-10-30T16:46:20Z","commit_id":null,"commit_url":null,"state_reason":null},{"event":"cross-referenced","created_at":"2022-11-03T05:04:54Z","source":{"issue":{"number":1021,"title":"Move axios back to ^0.27.2","html_url":"https://github.com/aehrc/pathling/pull/1021","repository":{"full_name":"aehrc/pathling"},"pull_request":{"merged_at":"2022-11-03T05:22:27Z","html_url":"https://github.com/aehrc/pathling/pull/1021"}}}},{"event":"cross-referenced","created_at":"2022-11-15T11:10:59Z","source":{"issue":{"number":1180,"title":"Change axios back as dependency.","html_url":"https://github.com/vpulim/node-soap/pull/1180","repository":{"full_name":"vpulim/node-soap"},"pull_request":{"merged_at":null,"html_url":"https://github.com/vpulim/node-soap/pull/1180"}}}},{"event":"cross-referenced","created_at":"2022-11-18T00:51:45Z","source":{"issue":{"number":4454,"title":"fix(deps): update dependency axios to v1","html_url":"https://github.com/openequella/openEQUELLA/pull/4454","repository":{"full_name":"openequella/openEQUELLA"},"pull_request":{"merged_at":"2022-12-05T22:10:58Z","html_url":"https://github.com/openequella/openEQUELLA/pull/4454"}}}},{"event"